/**
 * The locale picker's option list: plugin-contributed locales first (they are
 * why the user opened the menu), then this plugin's own alphabetical block.
 *
 * This — not the default — is the whole of a language plugin's influence on
 * the transcript surface. Read at call time, not module load: plugins register
 * during page boot, after this module is imported.
 */
function getTranscriptLocaleSuggestions() {
  return Array.from(
    new Set([
      ...getRegisteredTranscriptLocales(),
      ...BASE_TRANSCRIPT_LOCALE_SUGGESTIONS,
    ]),
  );
}

function normalizeTranscriptLocale(locale) {
  const trimmedLocale = locale?.trim().replace(/_/g, '-') ?? '';

  if (trimmedLocale.length === 0) {
    return AUTO_TRANSCRIPT_LOCALE;
  }

  try {
    const [canonicalLocale] = Intl.getCanonicalLocales(trimmedLocale);

    return canonicalLocale ?? trimmedLocale;
  } catch {
    return trimmedLocale;
  }
}

function resolveTranscriptLocale(locale) {
  const normalizedLocale = normalizeTranscriptLocale(locale);

  if (normalizedLocale.length > 0) {
    return normalizedLocale;
  }

  if (typeof document !== 'undefined') {
    const documentLocale = normalizeTranscriptLocale(
      document.documentElement.lang,
    );

    if (documentLocale.length > 0) {
      return documentLocale;
    }
  }

  if (typeof navigator !== 'undefined') {
    for (const language of navigator.languages ?? []) {
      const normalizedLanguage = normalizeTranscriptLocale(language);

      if (normalizedLanguage.length > 0) {
        return normalizedLanguage;
      }
    }

    const navigatorLocale = normalizeTranscriptLocale(navigator.language);

    if (navigatorLocale.length > 0) {
      return navigatorLocale;
    }
  }

  return 'en-US';
}

export {
  AUTO_TRANSCRIPT_LOCALE,
  BASE_TRANSCRIPT_LOCALE_SUGGESTIONS,
  DEFAULT_TRANSCRIPT_LOCALE,
  getTranscriptLocaleSuggestions,
  normalizeTranscriptLocale,
  resolveTranscriptLocale,
};
